    assertThat(runner.getLogger().getDebugMessages().stream().anyMatch(logMessage -> logMessage.getMsg().endsWith("Shutting down Record Processor for shard: {} with reason: {}")), is(true));
    // wait loop when records are processing
    assertThat(runner.getLogger().getDebugMessages().stream().filter(logMessage -> logMessage.getMsg().endsWith("Record Processor for shard {} still processing records, waiting before shutdown")).count(), is(2L));
    assertThat(runner.getLogger().getWarnMessages().stream().filter(logMessage -> logMessage.getMsg().endsWith("Record Processor for shard test-shard still running, but maximum wait time elapsed, checkpoint will be attempted")).count(), is(1L));
}

