    attributes.put("uuid", "unit-test-id");
    dos.write(CHECK_SPACE);
    dos.write(MORE_FLOWFILES);
    writeAttributes(attributes, dos);
    // Indicate 45 byte data frame, then stop after 5 bytes.
    dos.write(DATA_FRAME_FOLLOWS);
    dos.writeShort(45);
