            final String id = invocation.getArgument(1);
            final BundleCoordinate bundleCoordinate = invocation.getArgument(2);
            final ControllerServiceNode serviceNode = new ExtensionBuilder().identifier(id).type(type).bundleCoordinate(bundleCoordinate).controllerServiceProvider(serviceProvider).processScheduler(Mockito.mock(ProcessScheduler.class)).nodeTypeProvider(Mockito.mock(NodeTypeProvider.class)).validationTrigger(Mockito.mock(ValidationTrigger.class)).reloadComponent(Mockito.mock(ReloadComponent.class)).variableRegistry(variableRegistry).stateManagerProvider(Mockito.mock(StateManagerProvider.class)).extensionManager(extensionManager).buildControllerService();
            serviceProvider.onControllerServiceAdded(serviceNode);
