@Test
public void testStorageOptionsConfiguration() throws Exception {
    reset(storage);
    final TestRunner runner = buildNewRunner(getProcessor());
    final AbstractGCSProcessor processor = getProcessor();
    final GoogleCredentials mockCredentials = mock(GoogleCredentials.class);
    final StorageOptions options = processor.getServiceOptions(runner.getProcessContext(), mockCredentials);
    assertEquals("Project IDs should match", PROJECT_ID, options.getProjectId());
    assertEquals("Retry counts should match", RETRIES.intValue(), options.getRetrySettings().getMaxAttempts());
    assertSame("Credentials should be configured correctly", mockCredentials, options.getCredentials());
}

