public void testListingEmptyDir() throws InterruptedException, IOException {
    runner.setProperty(ListHDFS.DIRECTORY, "/test/emptyDir");
    proc.fileSystem.addFileStatus(new Path("hdfs", "hdfscluster:8020", "/test"), new FileStatus(1L, false, 1, 1L, 0L, 0L, create777(), "owner", "group", new Path("hdfs", "hdfscluster:8020", "/test/testFile.out")));
    proc.fileSystem.addFileStatus(new Path("hdfs", "hdfscluster:8020", "/test"), new FileStatus(1L, false, 1, 1L, 0L, 0L, create777(), "owner", "group", new Path("hdfs", "hdfscluster:8020", "/test/testFile.txt")));
    proc.fileSystem.addFileStatus(new Path("hdfs", "hdfscluster:8020", "/test"), new FileStatus(1L, true, 1, 1L, 0L, 0L, create777(), "owner", "group", new Path("hdfs", "hdfscluster:8020", "/test/emptyDir")));
    proc.fileSystem.addFileStatus(new Path("hdfs", "hdfscluster:8020", "/test"), new FileStatus(1L, true, 1, 1L, 0L, 0L, create777(), "owner", "group", new Path("hdfs", "hdfscluster:8020", "/test/testDir")));
    proc.fileSystem.addFileStatus(new Path("hdfs", "hdfscluster:8020", "/test/testDir"), new FileStatus(1L, false, 1, 1L, 0L, 0L, create777(), "owner", "group", new Path("hdfs", "hdfscluster:8020", "/test/testDir/1.txt")));
    proc.fileSystem.addFileStatus(new Path("hdfs", "hdfscluster:8020", "/test/testDir"), new FileStatus(1L, true, 1, 1L, 0L, 0L, create777(), "owner", "group", new Path("hdfs", "hdfscluster:8020", "/test/testDir/anotherDir")));
    proc.fileSystem.addFileStatus(new Path("hdfs", "hdfscluster:8020", "/test/testDir/anotherDir"), new FileStatus(1L, false, 1, 1L, 0L, 0L, create777(), "owner", "group", new Path("hdfs", "hdfscluster:8020", "/test/testDir/anotherDir/1.out")));
    proc.fileSystem.addFileStatus(new Path("hdfs", "hdfscluster:8020", "/test/testDir/anotherDir"), new FileStatus(1L, false, 1, 1L, 0L, 0L, create777(), "owner", "group", new Path("hdfs", "hdfscluster:8020", "/test/testDir/anotherDir/1.txt")));
    proc.fileSystem.addFileStatus(new Path("hdfs", "hdfscluster:8020", "/test/testDir/anotherDir"), new FileStatus(1L, false, 1, 1L, 0L, 0L, create777(), "owner", "group", new Path("hdfs", "hdfscluster:8020", "/test/testDir/anotherDir/2.out")));
    proc.fileSystem.addFileStatus(new Path("hdfs", "hdfscluster:8020", "/test/testDir/anotherDir"), new FileStatus(1L, false, 1, 1L, 0L, 0L, create777(), "owner", "group", new Path("hdfs", "hdfscluster:8020", "/test/testDir/anotherDir/2.txt")));
    proc.fileSystem.addFileStatus(new Path("hdfs", "hdfscluster:8020", "/test/testDir"), new FileStatus(1L, true, 1, 1L, 0L, 0L, create777(), "owner", "group", new Path("hdfs", "hdfscluster:8020", "/test/testDir/someDir")));
    proc.fileSystem.addFileStatus(new Path("hdfs", "hdfscluster:8020", "/test/testDir/someDir"), new FileStatus(1L, false, 1, 1L, 0L, 0L, create777(), "owner", "group", new Path("hdfs", "hdfscluster:8020", "/test/testDir/someDir/1.out")));
    // first iteration will not pick up files because it has to instead check timestamps.
    // We must then wait long enough to ensure that the listing can be performed safely and
    // run the Processor again.
    runner.run();
    Thread.sleep(TimeUnit.NANOSECONDS.toMillis(2 * ListHDFS.LISTING_LAG_NANOS));
    runner.run();
    // verify that no messages were logged at the error level
    verify(mockLogger, never()).error(anyString());
    final ArgumentCaptor<Throwable> throwableArgumentCaptor = ArgumentCaptor.forClass(Throwable.class);
    verify(mockLogger, atLeast(0)).error(anyString(), throwableArgumentCaptor.capture());
    // if error.(message, throwable) was called, ignore JobConf CNFEs since mapreduce libs are not included as dependencies
    assertTrue(throwableArgumentCaptor.getAllValues().stream().flatMap(Stream::of).// check that there are no throwables that are not of JobConf CNFE exceptions
    noneMatch(throwable -> !(throwable instanceof ClassNotFoundException && throwable.getMessage().contains("JobConf"))));
    verify(mockLogger, never()).error(anyString(), any(Object[].class));
    verify(mockLogger, never()).error(anyString(), any(Object[].class), any(Throwable.class));
    // assert that no files were listed
    runner.assertAllFlowFilesTransferred(ListHDFS.REL_SUCCESS, 0);
    // assert that no files were penalized
    runner.assertPenalizeCount(0);
}

