public void testMultipleMessagesPerFlowFile() throws IOException {
    final List<FlowFile> flowFiles = new ArrayList<>();
    flowFiles.add(runner.enqueue("John Doe, 48\nJane Doe, 47"));
    flowFiles.add(runner.enqueue("John Doe, 48\nJane Doe, 29"));
    final Map<FlowFile, Integer> msgCounts = new HashMap<>();
    msgCounts.put(flowFiles.get(0), 10);
    msgCounts.put(flowFiles.get(1), 20);
    final PublishResult result = createPublishResult(msgCounts, new HashSet<>(flowFiles), Collections.emptyMap());
    when(mockLease.complete()).thenReturn(result);
    runner.run();
    runner.assertAllFlowFilesTransferred(PublishKafkaRecord_1_0.REL_SUCCESS, 2);
    verify(mockLease, times(2)).publish(any(FlowFile.class), any(RecordSet.class), any(RecordSetWriterFactory.class), AdditionalMatchers.or(any(RecordSchema.class), isNull()), eq(null), eq(TOPIC_NAME), nullable(Function.class));
    verify(mockLease, times(0)).publish(any(FlowFile.class), any(Map.class), eq(null), any(byte[].class), eq(TOPIC_NAME), any(InFlightMessageTracker.class), nullable(Integer.class));
    verify(mockLease, times(1)).complete();
    verify(mockLease, times(0)).poison();
    verify(mockLease, times(1)).close();
    runner.assertAllFlowFilesContainAttribute("msg.count");
    assertEquals(1, runner.getFlowFilesForRelationship(PublishKafkaRecord_1_0.REL_SUCCESS).stream().filter(ff -> ff.getAttribute("msg.count").equals("10")).count());
    assertEquals(1, runner.getFlowFilesForRelationship(PublishKafkaRecord_1_0.REL_SUCCESS).stream().filter(ff -> ff.getAttribute("msg.count").equals("20")).count());
}

